// display-only: effect vs render
function Profile() {
  // render: describe the screen
  // effect: fetch the user AFTER the screen shows
  useEffect(() => { fetchUser(); }, []);
  return <p>Loading…</p>;
}

// display-only: the order
console.log('A: render');
useEffect(() => { console.log('C: effect'); });
console.log('B: still rendering');
// prints: A, B, then C

// display-only: dependencies
useEffect(() => {
  document.title = 'You clicked ' + count + ' times';
}, [count]); // re-runs only when count changes

// display-only: run once on load
useEffect(() => {
  fetch('/api/user').then(setUser);
}, []); // empty array: fetch once, when the screen first appears

// display-only: cleanup
useEffect(() => {
  const id = setInterval(tick, 1000);
  return () => clearInterval(id); // cleanup: stop the timer
}, []);

// display-only: the infinite-loop trap
useEffect(() => {
  setCount(count + 1); // sets state → re-renders → effect runs again…
}); // no array: infinite loop!

